/**
 * The capability matrix behind /compare. Each cell's detail and caveat carry
 * the product's own scope, so a check in two columns never claims equal scope.
 * Every third-party cell links the official page it was read from.
 */

// MARK: - Types

export const ESupport = { yes: 'yes', partial: 'partial', no: 'no', unknown: 'unknown' } as const
export type TSupport = (typeof ESupport)[keyof typeof ESupport]

export const SUPPORT_LABEL = {
  yes: 'Supported',
  partial: 'Partly supported',
  no: 'Not supported',
  unknown: 'Not documented',
} as const satisfies Record<TSupport, string>

export const COMPARE_PRODUCTS = [
  { id: 'kizuna', name: 'Kizuna', homepage: 'https://kizunasync.com' },
  { id: 'powersync', name: 'PowerSync', homepage: 'https://www.powersync.com' },
  { id: 'electric', name: 'Electric', homepage: 'https://electric-sql.com' },
  { id: 'zero', name: 'Zero', homepage: 'https://zero.rocicorp.dev' },
  { id: 'legend-state', name: 'Legend-State', homepage: 'https://legendapp.com/open-source/state' },
  { id: 'rxdb', name: 'RxDB', homepage: 'https://rxdb.info' },
  { id: 'watermelondb', name: 'WatermelonDB', homepage: 'https://watermelondb.dev' },
  { id: 'tinybase', name: 'TinyBase', homepage: 'https://tinybase.org' },
  { id: 'triplit', name: 'Triplit', homepage: 'https://www.triplit.dev' },
  { id: 'instantdb', name: 'InstantDB', homepage: 'https://www.instantdb.com' },
  { id: 'firestore', name: 'Firestore', homepage: 'https://firebase.google.com/docs/firestore' },
  { id: 'custom', name: 'A typical custom implementation', shortName: 'Custom', homepage: null },
] as const
export type TProductId = (typeof COMPARE_PRODUCTS)[number]['id']

export interface ICompareCell {
  value: TSupport
  detail: string
  caveat?: string
  sourceUrl?: string
}

export interface ICompareRow {
  id: string
  label: string
  definition: string
  cells: Record<TProductId, ICompareCell>
}

export interface ICompareGroup {
  id: string
  label: string
  rows: ICompareRow[]
}

