// MARK: - Helpers

/** Every distinct official source behind one product's cells, in row order. */
export function productSources(id: TProductId): string[] {
  const urls = COMPARE_GROUPS.flatMap((group) => group.rows.map((row) => row.cells[id].sourceUrl))

  return [...new Set(urls.filter((url): url is string => url?.startsWith('https://') === true))]
}
